Exponential blowup to linear: this inline recursive cost function is the spec - keep its semantics, fix its complexity.

def min_cost(steps, i=0):
    if i >= len(steps) - 1:
        return 0
    one = steps[i + 1] + min_cost(steps, i + 1)
    two = float('inf')
    if i + 2 < len(steps):
        two = steps[i + 2] + min_cost(steps, i + 2)
    return min(one, two)

